<?php
require_once __DIR__.'/../config/koneksi.php';require_role(['pj_sarpras','kasubbag_umum','admin']);
$date=$_GET['tanggal']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))$date=date('Y-m-d');
$s=$conn->prepare("SELECT r.id,r.nama_ruangan,h.id ceklist_id,h.verif_pj_sarpras,h.verif_kasubbag,COUNT(d.id) jumlah FROM ruangan r LEFT JOIN ceklist_harian h ON h.ruangan_id=r.id AND h.tanggal=? LEFT JOIN ceklist_detail d ON d.ceklist_harian_id=h.id GROUP BY r.id,h.id ORDER BY r.nama_ruangan");
$s->bind_param('s',$date);$s->execute();$rows=stmt_rows($s);$page_title='Rekap Verifikasi';include __DIR__.'/../includes/header.php';
?>
